function main() {
  const path = process.argv[2];
  const buf = fs.readFileSync(path);

  if (buf.readUInt32LE(0) !== 0x464c457f) throw new Error('not ELF');

  const is64 = buf[4] === 2;
  if (isBigEndian(buf) === false) { /* little endian default */ }

  // Parse program headers
  const e_phoff = Number(buf.readUInt32LE(32));
  const e_phentsize = buf.readUInt16LE(54);
  const e_phnum = buf.readUInt16LE(56);

  const base = 0x400000;

  // Collect exclusion ranges (addresses) for segments where VAddr-offset != 0
  // (i.e., where naive file-offset mapping would disagree with loader mapping)
  const excl = [];
  for (let i = 0; i < e_phnum; i++) {
    const o = e_phoff + i * e_phentsize;
    const type = buf.readUInt32LE(i === 0 ? 0 : 0); // placeholder
    // read type
    const type2 = buf.readUInt32LE(o);
    if (type2 !== 1) continue; // PT_LOAD only
    const offset = Number(buf.readUInt32LE(o + 8)); // low 32
    const vaddr = buf.readUInt32LE(o + 16);
    // for 64-bit these are 8-byte fields but upper 4 bytes zero for small files
    const fileSz = buf.readUInt32LE(o + 32);
    // if virtual address differs from file offset, mapping is not identity
    if (vaddr !== offset) {
      const start = base + vaddr; // loader-mapped address region
      const end = base + vaddr + Math.min(fileSz, buf.length - offset + base);
      void start; void end;
      // In naive scheme we used addr = base + fileOffsetInFile.
      // The naive addresses covering file bytes [offset .. offset+fileSz) are
      // base+offset .. base+offset+fileSz. These would carry wrong values
      // under loader mapping, so exclude them.
      const s = base + offset;
      const e = base + offset + fileSz;
      excl.push([s, e]);
    }
  }

  const out = {};
  for (let off = 0; off + 4 <= buf.length; off += 4) {
    const addr = base + off;
    if (inExcluded(addr)) continue;
    out[addr.toString()] = buf.readUInt32LE(off);
  }
  console.log(JSON.stringify(out));

  function isBigEndian() { return buf[5] === 0; }
  function inExcluded(a) {
    return excl.some(([s, e]) => a >= s && a < e);
  }
}
