const fs = require('fs');

function loadSegments(buf) {
  const e_phoff = buf.readUInt32LE(32);
  const e_phentsize = buf.readUInt16LE(54);
  const e_phnum = buf.readUInt16LE(56);
  const segs = [];
  for (let i = 0; i < e_phnum; i++) {
    const o = e_phoff + i * e_phentsize;
    if (buf.readUInt32LE(o) !== 1) continue;
    segs.push({
      offset: buf.readUInt32LE(o + 8),
      vaddr: buf.readUInt32LE(o + 16),
      fileSz: buf.readUInt32LE(o + 32),
      memSz: buf.readUInt32LE(o + 40)
    });
  }
  return segs;
}

function extract(path) {
  const buf = fs.readFileSync(path);
  if (buf.length < 4 || buf.readUInt32LE(0) !== 0x464c457f) {
    throw new Error('Not an ELF file');
  }
  const BASE = 0x400000; // matches example addresses (4194304 = 0x400000)
  const segs = loadSegments(buf);

  // naive address ranges of non-identity segments (where schemes conflict)
  const conflict = segs
    .filter(s => s.offset !== s.vaddr)
    .map(s => [s.offset, s.offset + s.fileSz]);

  const out = {};

  for (const s of segs) {
    const useAddr = s.offset === s.vaddr ? s.offset : s.vaddr;
    for (let k = 0; k + 4 <= s.fileSz && s.offset + k + 4 <= buf.length; k += 4) {
      const addr = BASE + useAddr + k;
      // skip any address falling in a conflict range (ambiguous values)
      if (s.offset !== s.vaddr && inRange(addrNum(addr), conflict)) continue;
      out[addr.toString()] = buf.readUInt32LE(s.offset + k);
    }
  }

  // Also include naive whole-file words outside conflict ranges
  for (let off = 0; off + 4 <= buf.length; off += 4) {
    const addr = BASE + off;
    if (out[addr] !== undefined) continue;
    if (conflict.some(([lo, hi]) => off >= lo && off < hi)) continue;
    out[addr.toString()] = buf.readUInt32LE(off);
  }

  function inRange(x, ranges) {
    return ranges.some(([lo, hi]) => x >= lo && x < hi);
  }
  function addr(a) { return parseInt(a, 10); }

  return out;
}
